import{_ as a,o as s,c as n,a3 as e}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"03 · ReAct 与规划：边想边做","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agent/03.md","filePath":"ai/agent/03.md"}'),l={name:"ai/agent/03.md"};function o(i,t,r,d,c,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_03-·-react-与规划-边想边做" tabindex="-1">03 · ReAct 与规划：边想边做 <a class="header-anchor" href="#_03-·-react-与规划-边想边做" aria-label="Permalink to &quot;03 · ReAct 与规划：边想边做&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>ReAct 的格式：Thought（思考）→ Action（行动）→ Observation（观察），循环往复。</li><li>为什么「先想再做」比「直接做」好，为什么「边做边看结果」比「只想不做」好。</li><li>另一种思路「先规划再执行」（Plan-and-Execute）和 ReAct 的区别。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>前两篇讲了 Agent 的组成和单次工具调用。这一篇讲<strong>多步任务里，模型怎么一步步推进</strong>。</p><p>本篇讲 4 个点：① ReAct 是什么 → ② 一个多步任务的完整记录 → ③ 为什么这么设计 → ④ 先规划再执行。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>ReAct = 让模型每一步先写下「我在想什么」，再决定「做什么」，看到结果后再想下一步。</strong> 名字来自 <strong>Re</strong>asoning（推理）+ <strong>Act</strong>ing（行动）。</p><h2 id="生活类比-侦探破案" tabindex="-1">生活类比：侦探破案 <a class="header-anchor" href="#生活类比-侦探破案" aria-label="Permalink to &quot;生活类比：侦探破案&quot;">​</a></h2><ul><li>只推理不调查的侦探：坐在家里空想，很容易想错（<strong>只想不做</strong>）。</li><li>只调查不推理的侦探：到处乱问，不知道自己在找什么（<strong>只做不想</strong>）。</li><li>好侦探：「凶手可能是左撇子 → <strong>去查</strong>谁是左撇子 → 发现管家是 → 那再<strong>查</strong>管家当晚在哪……」<strong>想和做交替推进，每一步的发现都会修正下一步的想法。</strong></li></ul><h2 id="一步步看-「《三体》作者今年多大-」" tabindex="-1">一步步看：「《三体》作者今年多大？」 <a class="header-anchor" href="#一步步看-「《三体》作者今年多大-」" aria-label="Permalink to &quot;一步步看：「《三体》作者今年多大？」&quot;">​</a></h2><p>可用工具：<code>search(query)</code> 搜索、<code>calculator(expr)</code> 计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought 1:  要知道作者年龄，先得知道作者是谁、哪年出生。</span></span>
<span class="line"><span>Action 1:   search(&quot;《三体》 作者&quot;)</span></span>
<span class="line"><span>Observation 1: 《三体》的作者是刘慈欣。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thought 2:  再查刘慈欣的出生年份。</span></span>
<span class="line"><span>Action 2:   search(&quot;刘慈欣 出生年份&quot;)</span></span>
<span class="line"><span>Observation 2: 刘慈欣，1963 年出生。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thought 3:  今年是 2026 年，算一下 2026 − 1963。</span></span>
<span class="line"><span>Action 3:   calculator(&quot;2026 - 1963&quot;)</span></span>
<span class="line"><span>Observation 3: 63</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thought 4:  信息齐了，可以回答。</span></span>
<span class="line"><span>Final Answer: 《三体》的作者是刘慈欣，1963 年出生，今年（2026 年）63 岁（生日没过的话是 62 岁）。</span></span></code></pre></div><p>注意第 2 步：「查出生年份」这个动作，是<strong>看到第 1 步的结果后</strong>才决定的。提前写死流程做不到这一点。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么要先写-thought-思考-而不是直接行动" tabindex="-1">为什么要先写 Thought（思考），而不是直接行动？ <a class="header-anchor" href="#为什么要先写-thought-思考-而不是直接行动" aria-label="Permalink to &quot;为什么要先写 Thought（思考），而不是直接行动？&quot;">​</a></h3><ul><li><strong>问题</strong>：模型直接输出行动，容易「想当然」：调错工具、漏掉步骤。</li><li><strong>方案</strong>：每次行动前，先把推理写出来（类似第 04 篇讲的思维链）。</li><li><strong>好处</strong>：写出来的推理成为后续生成的上下文，行动更有针对性；开发者也能看到它「为什么这么做」，方便调试。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>先写思考相当于打草稿，让行动有依据、更准确；同时推理过程可见，出错时容易定位原因。</p></div><h3 id="为什么要交替进行-而不是先全部想完再做" tabindex="-1">为什么要交替进行，而不是先全部想完再做？ <a class="header-anchor" href="#为什么要交替进行-而不是先全部想完再做" aria-label="Permalink to &quot;为什么要交替进行，而不是先全部想完再做？&quot;">​</a></h3><ul><li><strong>问题</strong>：很多信息只有执行之后才知道。不知道作者是谁，就没法提前决定「查谁的出生年份」。</li><li><strong>方案</strong>：想一步、做一步、看结果，再想下一步。</li><li><strong>好处</strong>：能根据真实结果随时调整，减少凭空推理带来的幻觉。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>因为后续步骤往往依赖前一步的结果，交替进行能用真实观察修正推理，比一次性想完更准确，也更少幻觉。</p></div><h3 id="怎么知道该停下来" tabindex="-1">怎么知道该停下来？ <a class="header-anchor" href="#怎么知道该停下来" aria-label="Permalink to &quot;怎么知道该停下来？&quot;">​</a></h3><ul><li><strong>问题</strong>：模型可能一直查下去，或在两个动作之间打转。</li><li><strong>方案</strong>：三重保险：① 模型判断信息够了，输出最终答案；② 最大轮数限制；③ 检测重复调用（同样的工具、同样的参数连续出现）。</li><li><strong>好处</strong>：不会死循环，成本可控。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>由模型判断完成并输出最终答案，同时程序设置最大轮数和重复检测兜底。</p></div><h2 id="另一种思路-先规划-再执行" tabindex="-1">另一种思路：先规划，再执行 <a class="header-anchor" href="#另一种思路-先规划-再执行" aria-label="Permalink to &quot;另一种思路：先规划，再执行&quot;">​</a></h2><p><strong>Plan-and-Execute（规划-执行）</strong>：先让模型列出完整计划，再一步步执行，必要时修改计划。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>计划：① 搜索三体作者  ② 搜索作者出生年份  ③ 计算年龄</span></span>
<span class="line"><span>执行：按步骤做 → 某一步结果出乎意料 → 回头修改计划</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th>ReAct</th><th>先规划再执行</th></tr></thead><tbody><tr><td>怎么推进</td><td>走一步看一步</td><td>先列全盘计划，再按计划做</td></tr><tr><td>适合</td><td>步骤少、不确定性高的任务</td><td>步骤多、结构清晰的任务</td></tr><tr><td>优点</td><td>灵活，随时调整</td><td>全局视角好，不容易跑偏</td></tr><tr><td>缺点</td><td>长任务容易迷失方向</td><td>计划可能不符合实际，要能重新规划</td></tr></tbody></table><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>ReAct</td><td>Reasoning 推理 + Acting 行动</td><td>推理和行动交替进行的 Agent 模式（2022 年提出）</td></tr><tr><td>Thought</td><td>思考</td><td>模型写下的推理过程</td></tr><tr><td>Action</td><td>行动</td><td>调用某个工具</td></tr><tr><td>Observation</td><td>观察</td><td>工具返回的结果</td></tr><tr><td>Final Answer</td><td>final 最终 + answer 答案</td><td>任务完成后的最终输出</td></tr><tr><td>Plan-and-Execute</td><td>plan 计划 + execute 执行</td><td>先规划再执行的 Agent 模式</td></tr><tr><td>Replanning</td><td>re 重新 + planning 规划</td><td>根据执行情况修改计划</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：介绍一下 ReAct。</strong></p><blockquote><p>ReAct 让模型交替输出推理（Thought）和行动（Action）：先推理下一步需要什么，再调用工具，拿到观察结果（Observation）后继续推理，直到得出最终答案。它把思维链的推理能力和工具调用结合起来：推理指导行动，行动的结果又修正推理，比只推理更少幻觉，比只行动更有方向。</p></blockquote><p><strong>Q：ReAct 和 Plan-and-Execute 有什么区别？</strong></p><blockquote><p>ReAct 是逐步决策，每一步都根据最新观察决定下一步，灵活但长任务容易偏离目标；Plan-and-Execute 先生成全局计划再执行，适合步骤多、结构清晰的任务，但需要在执行偏离预期时重新规划。</p></blockquote><p><strong>Q：Agent 陷入循环怎么办？</strong></p><blockquote><p>设置最大迭代次数；检测重复的工具调用；在提示里要求信息足够时立即给出答案；循环被中断时，返回已有的部分结果和失败原因。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>ReAct ≠ React（前端框架）</strong>：名字撞了，完全无关。</li><li><strong>Thought 不一定展示给用户</strong>：它主要给模型自己和开发者看。很多产品只展示最终答案。</li><li><strong>现在很多模型原生支持工具调用</strong>：不一定要严格按「Thought: / Action:」这种文本格式写，但「推理 → 行动 → 观察」的循环思想是一样的。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/04">Prompt 与采样参数</a>：Thought 就是思维链（CoT）用在 Agent 里。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/agent/02">工具调用</a>：每个 Action 就是一次工具调用。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/agent/04">记忆与 MCP</a>：步骤一多，历史越来越长，就需要记忆管理。</li><li><strong>原论文</strong>：Yao 等人，<em>ReAct: Synergizing Reasoning and Acting in Language Models</em>（2022）。你的 <code>E:\\Desktop\\1\\local_materials</code> 里有这篇 PDF。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：ReAct 的三个环节是什么？用侦探类比说一下。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>Thought（思考）→ Action（行动）→ Observation（观察），循环往复。像好侦探：先推理「可能是左撇子」，再去调查，看到调查结果后修正推理，再决定下一步查什么。</p></details><p><strong>Q2：为什么不让模型一次把所有步骤都想好再执行？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>后面的步骤往往依赖前面的结果：不知道作者是谁，就没法决定查谁的出生年份。交替进行能用真实结果修正推理，更准确，也更少幻觉。</p></details><p><strong>Q3：Agent 怎么避免停不下来？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>① 模型判断信息够了就输出最终答案；② 程序设置最大轮数；③ 检测重复的工具调用，出现就中断并返回原因。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能写出「三体作者年龄」例子的 Thought / Action / Observation 记录</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能讲清「先想再做」和「交替进行」各自解决什么问题（问题 → 方案 → 好处）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出 Agent 停止的三重保险</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能对比 ReAct 和 Plan-and-Execute，各说出一个适合的场景</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出 ReAct 名字的来历</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>步骤一多，对话历史越来越长，Agent 怎么「记住」重要的事？外部工具那么多，怎么统一接入？→ <a href="/study-hub/ai/agent/04">记忆与 MCP</a></li></ul>`,51)])])}const g=a(l,[["render",o]]);export{u as __pageData,g as default};
